if($('dashboard-groups')){$('dashboard-groups').onclick=e=>{const button=e.target.closest('[data-more],[data-less]');if(!button)return;const key=button.dataset.more||button.dataset.less;dashboardLimits[key]=button.dataset.more?(dashboardLimits[key]||5)+5:5;renderDashboard()};render();window.addEventListener('storage',render);window.addEventListener('focus',render);setInterval(render,60000);return}
function toggleOffer(){const no=field('decision').value==='no';$('offer-details').hidden=no;for(const el of $('offer-details').querySelectorAll('input,button'))el.disabled=no}
$('follow-fields').innerHTML=Array.from({length:4},(_,i)=>`<label>${i+1}. Nachfassen am<input type="date" name="follow${i+1}"></label>`).join('');const form=$('timeline-form'),field=n=>form.elements.namedItem(n);
$('objects').onclick=e=>{const button=e.target.closest('[data-edit]');if(!button)return;editing=items.find(x=>x.id===button.dataset.edit);if(!editing)return;form.reset();const r=records[editing.id]||{};for(const name of ['visit','visitTime','visitDuration','offer','follow1','follow2','follow3','follow4','next','nextTime','nextDuration','contact','phone','note'])field(name).value=r[name]||'';const latestVisit=[...editing.visits].sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];field('visit').value=r.visit||latestVisit?.date||'';field('visitTime').value=r.visitTime||latestVisit?.time||'';field('visitDuration').value=r.visitDuration||latestVisit?.duration||60;field('nextDuration').value=r.nextDuration||15;field('contact').value=editing.contact||'';field('phone').value=editing.phone||'';field('decision').value=info(editing,r).decision;field('objectStatus').value=info(editing,r).objectStatus;toggleOffer();$('edit-name').textContent=editing.name;$('edit-message').textContent='';for(const name of ['offer','follow1','follow2','follow3','follow4'])field(name).max=today();$('edit-dialog').showModal()};
field('decision').onchange=toggleOffer;
$('close').onclick=()=>$('edit-dialog').close();$('suggest').onclick=()=>{const r=Object.fromEntries(new FormData(form)),i=info(editing,r),base=i.lastContact;if(!base){$('edit-message').textContent='Bitte zuerst eine Besichtigung oder ein Angebots-/Kontaktdatum eintragen.';return}const d=new Date(base+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7);field('next').value=d.toISOString().slice(0,10);$('edit-message').textContent='Vorschlag übernommen. Du kannst das Datum frei ändern.'};
form.onsubmit=e=>{e.preventDefault();if(!editing||!form.reportValidity())return;const r=Object.fromEntries(new FormData(form));if(r.decision==='no'){for(const k of ['offer','follow1','follow2','follow3','follow4','next'])r[k]='';r.nextTime='';r.objectStatus='besichtigt'}if(r.decision==='yes'){if(!validDate(r.offer)){$('edit-message').textContent='Bitte das Datum des gestellten Angebots eintragen.';return}r.objectStatus='angebot'}let prev=validDate(r.offer);for(let n=1;n<=4;n++){const d=validDate(r['follow'+n]);if(!d)continue;if(!prev){$('edit-message').textContent='Bitte ein Angebotsdatum und die vorherigen Nachfasskontakte eintragen.';return}if(d<prev){$('edit-message').textContent='Nachfasskontakte müssen in zeitlicher Reihenfolge nach dem Angebot liegen.';return}if(n>1&&!r['follow'+(n-1)]){$('edit-message').textContent='Bitte die vorherigen Nachfasskontakte ergänzen.';return}prev=d}const next={...read(KEY,{}),[editing.id]:r};try{localStorage.setItem(KEY,JSON.stringify(next));records=next;const state=read(FAVORITES,{});if(editing.key&&state[editing.key]){const previous=info(editing,{}).objectStatus;state[editing.key].contact={name:r.contact||'',phone:r.phone||''};state[editing.key].status=r.objectStatus;state[editing.key].statusManual=r.objectStatus!==previous||r.decision==='no';localStorage.setItem(FAVORITES,JSON.stringify(state))}$('edit-dialog').close();$('message').textContent='Termine und Status gespeichert.';window.dispatchEvent(new Event('immobrain-calendar-changed'));render()}catch{$('edit-message').textContent='Speicherung fehlgeschlagen. Bitte Browserspeicher prüfen.'}};
$('month-prev').onclick=()=>{month.setUTCMonth(month.getUTCMonth()-1);renderCalendar()};$('month-next').onclick=()=>{month.setUTCMonth(month.getUTCMonth()+1);renderCalendar()};$('status-filter').onchange=render;window.addEventListener('storage',e=>{if([KEY,VIEWS,FAVORITES].includes(e.key)||e.key===null){records=read(KEY,{});render()}});window.addEventListener('focus',render);let day=today();setInterval(()=>{if(today()!==day){day=today();render()}},60000);render();
